  }
  process.stdout.write(verification.stdout);
} finally {
  rmSync(root, { recursive: true, force: true });
}

function installWithRetry(packages) {
  let last;
  for (let attempt = 1; attempt <= 5; attempt += 1) {
    last = spawnSync(
      process.platform === "win32" ? "npm.cmd" : "npm",
      [
        "install",
        "--ignore-scripts",
        "--no-audit",
        "--no-fund",
