  const url = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("fixture startup timeout")), 10000);
    lines.once("line", (line) => { clearTimeout(timer); resolve(line.trim()); });
    server.once("error", reject);
  });
